#!/usr/bin/env node
// One neutral source → both harnesses.
//   roles/*.md + config/routing.json → agents/*.md            (Claude Code subagents)
//                                    → codex/agents/*.toml     (Codex custom agents)
//                                    → codex/config.snippet.toml, codex/hooks.json
//                                    → routing block in hooks/register.ts (Claude mod)
// Also checks that every skill is portable (frontmatter: name + description only).
// `--check` writes nothing and fails if any generated file is out of date.

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseFrontmatter } from '../lib/frontmatter.mjs';
import { loadRouting, modelFor, RELAY_ROOT, TIERS } from '../lib/routing.mjs';

const GEN_NOTE = 'generated by scripts/build.mjs from roles/%s.md; edit the source and run `relay build`';
const READONLY_NOTE = 'You are read-only for project code: never create, edit or delete project code, and never commit. You may write only an expressly assigned report output.';
const SKILL_KEYS = new Set(['name', 'description']);

export function loadRoles(root = RELAY_ROOT) {
  const dir = join(root, 'roles');
  return readdirSync(dir)
    .filter((f) => f.endsWith('.md'))
    .sort()
    .map((f) => {
      const { data, body } = parseFrontmatter(readFileSync(join(dir, f), 'utf8'));
      const name = f.replace(/\.md$/, '');
      if (data.name !== name) throw new Error(`roles/${f}: name must be "${name}"`);
      if (!TIERS.includes(data.tier)) throw new Error(`roles/${f}: tier must be one of ${TIERS.join(', ')}`);
      if (!data.description) throw new Error(`roles/${f}: description is required`);
      return { ...data, body: body.trim() };
    });
}

function yamlString(s) {
  return /[:#\-?{}[\],&*!|>'"%@`]/.test(s) || s !== s.trim() ? JSON.stringify(s) : s;
}

export function claudeAgent(role, routing) {
  const tier = modelFor(routing, role.tier, 'claude');
  const lines = ['---', `# ${GEN_NOTE.replace('%s', role.name)}`, `name: ${role.name}`, `description: ${yamlString(role.description)}`];
  lines.push(`model: ${tier.model}`);
  lines.push(`effort: ${role.effort ?? tier.effort}`);
  if (role.tools?.length) lines.push(`tools: ${role.tools.join(', ')}`);
  if (role.readonly) lines.push('disallowedTools: Edit, NotebookEdit');
  if (role.maxTurns) lines.push(`maxTurns: ${role.maxTurns}`);
  if (role.color) lines.push(`color: ${role.color}`);
  lines.push('---', '');
  return lines.join('\n') + role.body + '\n';
}

export function codexAgent(role, routing) {
  const body = role.readonly ? `${READONLY_NOTE}\n\n${role.body}` : role.body;
  if (body.includes("'''")) throw new Error(`roles/${role.name}.md: body may not contain ''' (TOML literal string)`);
  return [
    `# ${GEN_NOTE.replace('%s', role.name)}`,
    `name = ${JSON.stringify(`relay-${role.name}`)}`,
    `description = ${JSON.stringify(role.description)}`,
    '# Model and effort are selected on dispatch and enforced by the spawn hook.',
    `developer_instructions = '''`,
    body,
    `'''`,
    '',
  ].join('\n');
}

export function codexConfigSnippet(routing) {
  const tier = modelFor(routing, routing.defaultSubagentTier, 'codex');
  return [
    '# generated by scripts/build.mjs from config/routing.json',
    '# Backstop for any spawn that names no model: route it to a deliberate tier',
    '# instead of silently inheriting the session model.',
    '[agents]',
    `default_subagent_model = ${JSON.stringify(tier.model)}`,
    `default_subagent_reasoning_effort = ${JSON.stringify(tier.effort)}`,
    '',
  ].join('\n');
}

export function codexHooks(plugin = false) {
  const root = plugin ? '${PLUGIN_ROOT}' : '__RELAY_ROOT__';
  const cmd = (script, args = '') => ({ type: 'command', command: `node "${root}/hooks/${script}"${args}` });
  const shell = 'Bash|shell|exec_command|local_shell|unified_exec';
  return (
    JSON.stringify(
      {
        $comment: 'generated by scripts/build.mjs; `relay setup codex <project>` installs this as <project>/.codex/hooks.json with __RELAY_ROOT__ resolved',
        hooks: {
          SessionStart: [{ hooks: [cmd('session-start.mjs', ' --harness codex')] }],
          PreToolUse: [
            { matcher: 'spawn_agent|Agent', hooks: [cmd('codex-spawn.mjs')] },
            { matcher: shell, hooks: [cmd('retest-guard.mjs'), cmd('protect-tests.mjs')] },
            { matcher: 'apply_patch|Edit|Write', hooks: [cmd('protect-tests.mjs')] },
          ],
          PostToolUse: [{ matcher: shell, hooks: [cmd('retest-guard.mjs')] }],
        },
      },
      null,
      2,
    ) + '\n'
  );
}

export function modRouting(routing, roles) {
  const { $comment, ...unrouted } = routing.unrouted ?? {};
  const b = routing.budget;
  return {
    tiers: Object.fromEntries(TIERS.map((t) => [t, modelFor(routing, t, 'claude').model])),
    roles: Object.fromEntries(roles.map((r) => [r.name, r.tier])),
    unrouted,
    budget: {
      fiveHour: b.fiveHour,
      sevenDay: b.sevenDay,
      tight: { capStrongTo: b.tight.capStrongTo, exempt: b.tight.exempt },
      critical: {
        capStrongTo: b.critical.capStrongTo,
        exempt: b.critical.exempt,
        denyNewSpawns: b.critical.denyNewSpawns,
        hide: b.critical.hide,
      },
    },
  };
}

export function injectModRouting(source, routingObject) {
  const start = '// <relay:generated>';
  const end = '// </relay:generated>';
  const i = source.indexOf(start);
  const j = source.indexOf(end);
  if (i === -1 || j === -1) throw new Error('hooks/register.ts: generated markers not found');
  const headerEnd = source.indexOf('\n', i) + 1;
  const block = `const ROUTING = ${JSON.stringify(routingObject, null, 2)} as const satisfies Routing\n`;
  return source.slice(0, headerEnd) + block + source.slice(j);
}

export function checkSkills(root = RELAY_ROOT) {
  const problems = [];
  const dir = join(root, 'skills');
  for (const name of readdirSync(dir).sort()) {
    const file = join(dir, name, 'SKILL.md');
    if (!existsSync(file)) {
      problems.push(`skills/${name}: missing SKILL.md`);
      continue;
    }
    const { data } = parseFrontmatter(readFileSync(file, 'utf8'));
    for (const k of Object.keys(data)) if (!SKILL_KEYS.has(k)) problems.push(`skills/${name}: frontmatter key "${k}" is not portable (Codex and the Agent Skills spec take name + description)`);
    if (data.name !== name) problems.push(`skills/${name}: name must equal the folder name`);
    if (!data.description) problems.push(`skills/${name}: description is required`);
    else if (data.description.length > 1024) problems.push(`skills/${name}: description is ${data.description.length} chars (max 1024)`);
  }
  return problems;
}

export function outputs(root = RELAY_ROOT) {
  const routing = loadRouting(root);
  const roles = loadRoles(root);
  const files = new Map();
  for (const role of roles) {
    files.set(join('agents', `${role.name}.md`), claudeAgent(role, routing));
    files.set(join('codex', 'agents', `relay-${role.name}.toml`), codexAgent(role, routing));
  }
  files.set(join('codex', 'config.snippet.toml'), codexConfigSnippet(routing));
  files.set(join('codex', 'hooks.json'), codexHooks());
  files.set(join('codex', 'hooks.plugin.json'), codexHooks(true));
  const modPath = join('hooks', 'register.ts');
  files.set(modPath, injectModRouting(readFileSync(join(root, modPath), 'utf8'), modRouting(routing, roles)));
  return files;
}

export function main(args = process.argv.slice(2), root = RELAY_ROOT) {
  const check = args.includes('--check');
  const problems = checkSkills(root);
  const stale = [];
  for (const [rel, content] of outputs(root)) {
    const abs = join(root, rel);
    const current = existsSync(abs) ? readFileSync(abs, 'utf8') : undefined;
    if (current === content) continue;
    if (check) stale.push(rel);
    else writeFileSync(abs, content);
  }
  for (const p of problems) console.error(`✗ ${p}`);
  if (check && stale.length) console.error(`✗ out of date (run \`relay build\`): ${stale.join(', ')}`);
  if (problems.length || stale.length) return 1;
  console.log(check ? '✓ generated files are up to date; skills are portable' : '✓ build complete');
  return 0;
}

if (import.meta.url === `file://${process.argv[1]}`) process.exit(main());
